// ---- shared client-data helpers (used by the transcribed bindings below) ----------------
namespace
{
    const uint32_t kSpellDbc = 0xAD49D0;        // Spell.dbc container (ecx for 0x4CFD20)
    const uint32_t kSpellIconDbc = 0xAD488C;    // SpellIcon.dbc container
    const uint32_t kSpellRecordSize = 0x2A8;    // bytes 0x4CFD20 copies

    bool FetchSpellRecord(uint32_t spellId, void* out)
    {
        typedef int(__thiscall* GetRec_t)(void*, uint32_t, void*);
        return reinterpret_cast<GetRec_t>(0x4CFD20)(reinterpret_cast<void*>(kSpellDbc), spellId, out) != 0;
    }

    const uint32_t kChrClassesDbc = 0xAD3404;   // ChrClasses.dbc container (from FUN_100b13c0)

    // FUN_100b2470 / FUN_100b13c0, generalised: every DBC lookup in this client has the same shape --
    // container[+0x20][id - container[+0x10]], bounds at +0x0C (max) and +0x10 (min).
    uint32_t DbcRow(uint32_t container, uint32_t id)
    {
        uint32_t maxId = *reinterpret_cast<uint32_t*>(container + 0x0C);
        uint32_t minId = *reinterpret_cast<uint32_t*>(container + 0x10);
        uint32_t rows  = *reinterpret_cast<uint32_t*>(container + 0x20);
        if (!rows || id < minId || id > maxId)
            return 0;
        return *reinterpret_cast<uint32_t*>(rows + (id - minId) * 4);
    }

    const char* DbcRowString(uint32_t container, uint32_t id, uint32_t fieldOffset)
    {
        uint32_t row = DbcRow(container, id);
        return row ? *reinterpret_cast<const char**>(row + fieldOffset) : nullptr;
    }

    const char* SafeStr(const char* s) { return (s && *s) ? s : nullptr; }
}

// ---- SetCanSeeAppearances / SetLevelScaling -----------------------------------------------------
// The two character-creation toggles. Both were stubs, so the creator recorded the player's choice
// (NewCharacterSetupUtil stores it, then replays it on PLAYER_LOGIN) and then handed it to a no-op.
//
// Transcribed from ghidra-ext/out/bindings/{SetCanSeeAppearances,SetLevelScaling}.c. Both build a
// packet the same way the client does everywhere else (GenPacket / PutInt32 opcode / body /
// m_read = 0 / SendPacket / Release -- same shape as CustomLua::PortGraveyard upstream).
//
//   SetCanSeeAppearances(items, spells) -> CMSG 0x6A3, two u8 bodies, returns true.
//       Server side EXISTS: mod-ascension-compat handles CMSG_SET_CAN_SEE_APPEARANCES (0x06A3)
//       via HandleSetAppearanceVisibility, and reports state back with SMSG_CAN_SEE_APPEARANCES_INFO
//       (0x6A2), whose layout we already verified live.
//
//   SetLevelScaling(enabled) -> CMSG 0x667, one u32 body, no return values. The original gates on
//       the client action check first (FUN_10111ce0(0x11) -- action 17, Forbidden), so we do too.
//       Server side EXISTS, in a DIFFERENT module: mod-destiny-weaver owns CMSG_SET_LEVEL_SCALING
//       (0x0667) via DestinyWeaver::HandleClientLevelScalingPacket, reading a u32 and storing the
//       per-character choice in character_settings under "core.destiny_weaver". It is registered
//       both through AscensionCompatOpcodes::Claim and its own CanPacketReceiveEarly. Grepping only
//       AscensionCompat.cpp made it look absent -- this is a multi-module tree.
static int Asc_SetCanSeeAppearances(lua_State* L)
{
    const int8_t items  = lua_toboolean(L, 1) ? 1 : 0;
    const int8_t spells = lua_toboolean(L, 2) ? 1 : 0;

    CDataStore pkt{};
    CDataStore::GenPacket(&pkt);
    CDataStore::PutInt32(&pkt, 0x6A3);
    CDataStore::PutInt8(&pkt, items);
    CDataStore::PutInt8(&pkt, spells);
    pkt.m_read = 0;
    ClientServices::SendPacket(&pkt);
    CDataStore::Release(&pkt);

    AscLog::Printf("SetCanSeeAppearances(%d, %d) -> CMSG 0x6A3", items, spells);
    lua_pushboolean(L, 1);
    return 1;
}

static int Asc_SetLevelScaling(lua_State* L)
{
    // action 17 = Enum.UIActionType.Forbidden, the same gate CanPerformAction uses
    int allowed = 1;
    __try { allowed = reinterpret_cast<int(__cdecl*)(uint32_t)>(0x5191C0)(17); }
    __except (EXCEPTION_EXECUTE_HANDLER) { allowed = 1; }
    if (!allowed)
    {
        AscLog::Printf("SetLevelScaling: blocked by the client action gate");
        return 0;
    }

    const int32_t enabled = lua_toboolean(L, 1) ? 1 : 0;

    CDataStore pkt{};
    CDataStore::GenPacket(&pkt);
    CDataStore::PutInt32(&pkt, 0x667);
    CDataStore::PutInt32(&pkt, enabled);
    pkt.m_read = 0;
    ClientServices::SendPacket(&pkt);
    CDataStore::Release(&pkt);

    AscLog::Printf("SetLevelScaling(%d) -> CMSG 0x667", enabled);
    return 0;
}

