// ---- GetClassInfo -------------------------------------------------------------------------------
// Transcribed from ghidra-ext/out/bindings/GetClassInfo.c (handler_GetClassInfo @ 0x100D8FA0).
// The CoA 21-class picker needs it: CharacterCreate.lua:1741 does
//   className, classFile, enabled = GetClassInfo(classID)
// inside `for i = 1, 21 do ... COA_CLASS_ORDER[i] ... C_CharacterCreate.CanCreateClass(classID)`.
//
// The original: fetch the id argument, look it up via FUN_100b13c0 (the ChrClasses.dbc container at
// 0xAD3404, same shape as every other DBC lookup here), and on a miss push three nils and return 3.
// On a hit it pushes record[4] and record[7] as strings -- Name and Filename once the client's loaded
// record collapses each localised string to a single pointer -- then record[0], the class id, as the
// third value (the Lua caller names it `enabled` and only tests the first two for nil).
static int Asc_GetClassInfo(lua_State* L)
{
    const uint32_t classId = (uint32_t)(int)lua_tonumber(L, 1);
    const char* name = nullptr;
    const char* file = nullptr;
    uint32_t id = 0;
    bool found = false;

    __try
    {
        uint32_t row = DbcRow(kChrClassesDbc, classId);
        if (row)
        {
            found = true;
            name = SafeStr(reinterpret_cast<const char**>(row)[4]);   // Name
            file = SafeStr(reinterpret_cast<const char**>(row)[7]);   // Filename
            id   = reinterpret_cast<uint32_t*>(row)[0];               // ID
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        AscLog::Printf("GetClassInfo(%u): faulted reading ChrClasses", classId);
        found = false;
    }

    if (!found || !name || !file)
    {
        lua_pushnil(L); lua_pushnil(L); lua_pushnil(L);
        return 3;
    }
    lua_pushstring(L, name);
    lua_pushstring(L, file);
    lua_pushnumber(L, (double)id);
    return 3;
}


// ---- SuggestInvite ------------------------------------------------------------------------------
// Transcribed from ghidra-ext/out/bindings/SuggestInvite.c (FUN_10274610). FrameXML's
// GlobalFunctions.lua:230 does hooksecurefunc("SuggestInvite", ...) at load, and ChatFrame.lua /
// UnitPopup.lua call it -- so a nil here fails the hook and takes the rest of that file with it.
// Wire format: CMSG 0x584 with an lpstring (u32 length, then that many bytes, no NUL) -- the same
// string convention as FUN_100d3680 on the receive side.
static int Asc_SuggestInvite(lua_State* L)
{
    const char* name = lua_isstring(L, 1) ? tostring(L, 1) : nullptr;
    if (!name || !*name)
        return 0;

    uint32_t len = 0;
    while (name[len]) ++len;

    CDataStore pkt{};
    CDataStore::GenPacket(&pkt);
    CDataStore::PutInt32(&pkt, 0x584);
    CDataStore::PutInt32(&pkt, (int32_t)len);
    for (uint32_t i = 0; i < len; ++i)
        CDataStore::PutInt8(&pkt, (int8_t)name[i]);
    pkt.m_read = 0;
    ClientServices::SendPacket(&pkt);
    CDataStore::Release(&pkt);

    AscLog::Printf("SuggestInvite('%s') -> CMSG 0x584", name);
    lua_pushboolean(L, 1);
    return 1;
}

