// ---- GetCustomGameMode / GetJsonCacheCategory ---------------------------------------------------
// Both were Stub1 (nil), and both feed code that immediately uses the result as a number or a table.
//
// GetCustomGameMode: C_GameMode.lua:31 does `local activeModes = GetCustomGameMode()` then
// `bit.contains(activeModes, value)` for every Enum.GameMode -- nil there is the
// "bit.lua:27: bad argument #1 to 'band'" seen in world. Returning 0 is not a placeholder: it is
// Enum.GameMode.None, and it is the accurate value for this realm. The enum covers per-CHARACTER
// custom modes (Random, Ironman, Draft, WildCard, Felforged ...); Conquest of Azeroth is a REALM
// mode in the separate Enum.RealmGameMode, so no custom mode is active here. If we ever run a draft
// or wildcard realm this must come from the real state instead (the original reads an internal
// object via FUN_1031EF10 and masks off 0x800).
static int Asc_GetCustomGameMode(lua_State* L)
{
    lua_pushnumber(L, 0.0);     // Enum.GameMode.None
    return 1;
}

// GetJsonCacheCategory: MapPOI.lua:72 does `pairs(GetJsonCacheCategory("AREA_POI_PAYLOAD"))`.
// An empty table is the truthful answer while nothing populates the client's JSON cache -- the
// payloads arrive from the server and ours does not send them.
static int Asc_GetJsonCacheCategory(lua_State* L)
{
    lua_createtable(L, 0, 0);
    return 1;
}

